import type { ReactElement } from "react";
import { IconCrossSmall } from "@registry/icons/central";
import { Icon } from "@registry/ui/icon";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { useBadgePart } from "./badge.context";
import { badgeVariants } from "./badge.variants";

export type BadgeCloseButtonProps = Omit<PressableProps, "asChild" | "busy" | "children" | "disabled">;

/**
 * The badge's trailing dismiss control.
 *
 * A pressable of its own rather than a mode of the root, which is what keeps a
 * dismiss from also firing the badge's `onPress`: the two gestures belong to two
 * detectors, and the inner one claims the tap.
 *
 * The root composes one in whenever `onClose` is set, so reach for this by hand
 * only to place it somewhere other than last — before an `EndContent`, say.
 *
 * The glyph is left bare: it inherits the badge's icon size and its surface's
 * colour from the root's `IconDefaultsProvider`, so a dismiss on a `danger`
 * badge is tinted without being told.
 *
 * `fade` rather than the root's `scale` — a spring on a glyph this small reads
 * as a jitter rather than as a press.
 */
export function BadgeCloseButton({
	accessibilityLabel = "Remove",
	className,
	feedback = "fade",
	...props
}: BadgeCloseButtonProps): ReactElement {
	const { size, isDisabled } = useBadgePart("Badge.CloseButton");

	return (
		<Pressable
			accessibilityLabel={accessibilityLabel}
			accessibilityRole="button"
			className={badgeVariants({ size }).closeButton({ className })}
			disabled={isDisabled}
			feedback={feedback}
			{...props}
		>
			<Icon icon={IconCrossSmall} />
		</Pressable>
	);
}
BadgeCloseButton.displayName = "DelacourUI.Badge.CloseButton";

import type { ReactElement } from "react";
import { View } from "react-native";
import type { BadgeSlotProps } from "./badge.types";
import { badgeVariants } from "./badge.variants";

/**
 * A centred wrapper for trailing content that is not an `Icon`.
 *
 * An `Icon` needs no wrapper: it inherits the badge's icon size and its
 * surface's colour from the root's `IconDefaultsProvider`.
 */
export function BadgeEndContent({ className, ...props }: BadgeSlotProps): ReactElement {
	return <View className={badgeVariants().endContent({ className })} {...props} />;
}
BadgeEndContent.displayName = "DelacourUI.Badge.EndContent";

import type { ReactElement } from "react";
import type { TextProps } from "react-native";
import { Text } from "@registry/ui/text";
import { useBadgePart } from "./badge.context";
import { badgeVariants } from "./badge.variants";

export type BadgeLabelProps = TextProps & { className?: string };

/**
 * The badge's text.
 *
 * Carries its own colour and type scale, read from the badge's context: a React
 * Native `View` does not cascade colour to a `Text` descendant, so a colour set
 * on the root would be lost.
 *
 * The class is passed rather than inherited even though the badge publishes the
 * same one through `TextClassProvider` — the two agree, and stating it here
 * keeps the label correct if it is ever rendered somewhere the provider is not.
 */
export function BadgeLabel({ className, ...props }: BadgeLabelProps): ReactElement {
	const { variant, color, size } = useBadgePart("Badge.Label");
	return <Text className={badgeVariants({ size, variant, color }).label({ className })} {...props} />;
}
BadgeLabel.displayName = "DelacourUI.Badge.Label";

import type { ReactElement } from "react";
import { View } from "react-native";
import type { BadgeSlotProps } from "./badge.types";
import { badgeVariants } from "./badge.variants";

/**
 * A centred wrapper for leading content that is not an `Icon` — a status dot, an
 * avatar.
 *
 * An `Icon` needs no wrapper: it inherits the badge's icon size and its
 * surface's colour from the root's `IconDefaultsProvider`.
 */
export function BadgeStartContent({ className, ...props }: BadgeSlotProps): ReactElement {
	return <View className={badgeVariants().startContent({ className })} {...props} />;
}
BadgeStartContent.displayName = "DelacourUI.Badge.StartContent";

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { BadgeColor, BadgeSize, BadgeVariant } from "./badge.variants";

export type BadgeContextValue = {
	/** Size of the badge. */
	size: BadgeSize;
	/** How the badge's surface is painted. */
	variant: BadgeVariant;
	/** What the badge's surface means. */
	color: BadgeColor;
	/** Whether the badge is disabled. */
	isDisabled: boolean;
};

const BadgeContext = createContext<BadgeContextValue | null>(null);

/**
 * Supplies the enclosing badge's variant, colour, size and state to its subtree.
 *
 * Lives in its own module, importing nothing but `badge.variants`, so a part can
 * read it without importing `./badge`. That import would close a cycle, and
 * Metro serves a partially initialised module for a cycle — leaving the context
 * `undefined` at import time and red-boxing the app on a cold start.
 */
export function BadgeProvider({ value, children }: { value: BadgeContextValue; children: ReactNode }): ReactElement {
	return <BadgeContext value={value}>{children}</BadgeContext>;
}
BadgeProvider.displayName = "DelacourUI.Badge.Provider";

/** The enclosing badge's context, or null outside a `<Badge>`. */
export function useBadgeContext(): BadgeContextValue | null {
	return use(BadgeContext);
}

/**
 * Reads the enclosing badge's variant, colour, size and state.
 *
 * Lets a custom child style itself to match without the badge having to pass
 * props down through every slot. Throws outside a `<Badge>` — use
 * {@link useBadgeContext} where the enclosing badge is optional.
 */
export function useBadge(): BadgeContextValue {
	const context = useBadgeContext();
	if (!context) {
		throw new Error("useBadge must be called inside a <Badge>.");
	}
	return context;
}

/**
 * The enclosing badge's context, for a compound part that cannot work without
 * one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useBadge}, whose error message names the hook rather than
 * a part.
 */
export function useBadgePart(component: string): BadgeContextValue {
	const context = useBadgeContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <Badge>.`);
	}
	return context;
}

import { Children, type ReactElement, type ReactNode, useMemo } from "react";
import { View } from "react-native";
import { IconDefaultsProvider } from "@registry/ui/icon";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { TextClassProvider } from "@registry/ui/text/text.context";
import { type BadgeContextValue, BadgeProvider } from "./badge.context";
import {
	BADGE_FOREGROUND_TOKEN,
	type BadgeColor,
	type BadgeSize,
	type BadgeVariant,
	badgeVariants,
	resolveBadgeInteractive,
} from "./badge.variants";
import { BadgeCloseButton } from "./badge-close-button";
import { BadgeEndContent } from "./badge-end-content";
import { BadgeLabel } from "./badge-label";
import { BadgeStartContent } from "./badge-start-content";

export type BadgeProps = Omit<PressableProps, "asChild" | "busy" | "children" | "disabled"> & {
	/** How the surface is painted. */
	variant?: BadgeVariant;
	/** What the surface means. */
	color?: BadgeColor;
	size?: BadgeSize;
	isDisabled?: boolean;
	/** Composes a trailing dismiss control in. Its press never reaches `onPress`. */
	onClose?: () => void;
	/** Name a screen reader gives the dismiss control. Defaults to `Remove`. */
	closeAccessibilityLabel?: string;
	children?: ReactNode;
};

function BadgeRoot({
	variant = "solid",
	color = "default",
	size = "md",
	isDisabled = false,
	onClose,
	closeAccessibilityLabel,
	onPress,
	onLongPress,
	haptic,
	feedback = "scale",
	pressedScale,
	pressedOpacity,
	className,
	children,
	...props
}: BadgeProps): ReactElement {
	const context = useMemo<BadgeContextValue>(
		() => ({ variant, color, size, isDisabled }),
		[variant, color, size, isDisabled]
	);

	const slots = badgeVariants({ color, isDisabled, size, variant });

	// Icons composed into the badge adopt these unless told otherwise.
	const iconClassName = slots.icon();
	const foregroundToken = BADGE_FOREGROUND_TOKEN[variant][color];
	const iconDefaults = useMemo(
		() => ({ className: iconClassName, color: foregroundToken }),
		[iconClassName, foregroundToken]
	);

	const content = useMemo(() => wrapTextChildren(children), [children]);
	const rootClassName = slots.root({ className });

	const inner = (
		<IconDefaultsProvider value={iconDefaults}>
			<TextClassProvider value={slots.label()}>
				{content}
				{onClose ? <BadgeCloseButton accessibilityLabel={closeAccessibilityLabel} onPress={onClose} /> : null}
			</TextClassProvider>
		</IconDefaultsProvider>
	);

	// A badge with nothing to do stays a plain box — see `resolveBadgeInteractive`.
	if (!resolveBadgeInteractive({ onPress, onLongPress })) {
		return (
			<BadgeProvider value={context}>
				<View className={rootClassName} {...props}>
					{inner}
				</View>
			</BadgeProvider>
		);
	}

	return (
		<BadgeProvider value={context}>
			<Pressable
				accessibilityRole="button"
				className={rootClassName}
				disabled={isDisabled}
				feedback={feedback}
				haptic={haptic}
				onLongPress={onLongPress}
				onPress={onPress}
				pressedOpacity={pressedOpacity}
				pressedScale={pressedScale}
				{...props}
			>
				{inner}
			</Pressable>
		</BadgeProvider>
	);
}

/**
 * Wraps bare text children in a `Badge.Label`.
 *
 * React Native cannot render a string outside a `<Text>`, so `<Badge>New</Badge>`
 * would otherwise crash. Consecutive strings and numbers are collected into a
 * single label rather than one each — `{count} left` is one piece of text, and
 * wrapping the parts separately would space them apart by the badge's gap.
 */
function wrapTextChildren(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		output.push(<BadgeLabel key={`label-${output.length}`}>{run.join("")}</BadgeLabel>);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
	}
	flushRun();

	return output;
}

/**
 * A compact label for status, category or count — composed from parts rather
 * than configured by flags.
 *
 * Two axes describe the surface: `variant` says how it is painted (`solid`,
 * `soft`, `outline`, `ghost`) and `color` says what it means (`default`,
 * `primary`, `success`, `warning`, `danger`, `info`). They are orthogonal, so
 * every one of the twenty-four pairings is reachable without the library naming
 * each combination.
 *
 * **A badge is content until it is given something to do.** With no `onPress` or
 * `onLongPress` it renders a plain `View` — no gesture detector, and nothing
 * announced to assistive technology as a control. Supply either and the root
 * becomes a `Pressable`, inheriting `feedback`, `haptic` and the rest; only the
 * default differs, `scale`.
 *
 * `onClose` composes a dismiss control in at the end. It is a pressable of its
 * own, so dismissing never also fires `onPress`.
 *
 * Plain string or number children are wrapped in a `Badge.Label` automatically;
 * pass the compound parts when a layout needs more control.
 *
 * Icons are composed in, not passed as props. Anything in the subtree inherits
 * the badge's icon size and its surface's colour, so an `Icon` needs nothing but
 * the glyph. Text works the same way — a bare `<Text>` comes out at the label's
 * colour and type scale without being told.
 *
 * @example
 * <Badge color="success" variant="soft">Active</Badge>
 *
 * @example
 * <Badge color="warning" variant="outline">
 *   <Icon icon={IconStar} />
 *   <Badge.Label>Premium</Badge.Label>
 * </Badge>
 *
 * @example
 * <Badge onClose={() => remove(tag)} onPress={() => filter(tag)}>
 *   {tag}
 * </Badge>
 */
export const Badge = Object.assign(BadgeRoot, {
	/** The badge's text. Picks its colour and type scale from the badge's variant, colour and size. */
	Label: BadgeLabel,
	/** A centred wrapper for leading content that is not an `Icon` — a status dot, an avatar. */
	StartContent: BadgeStartContent,
	/** A centred wrapper for trailing content that is not an `Icon`. */
	EndContent: BadgeEndContent,
	/** The trailing dismiss control. Composed in automatically whenever `onClose` is set. */
	CloseButton: BadgeCloseButton,
	displayName: "DelacourUI.Badge",
});

import type { ViewProps } from "react-native";

/**
 * The shape of a badge's leading and trailing slots.
 *
 * Shared by `Badge.StartContent` and `Badge.EndContent`, which are identical
 * apart from where the root places them, so it lives in a leaf rather than in
 * one of the two files arbitrarily.
 */
export type BadgeSlotProps = ViewProps & { className?: string };

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";

/** How the surface is painted. Orthogonal to {@link BADGE_COLORS}. */
export const BADGE_VARIANTS = ["solid", "soft", "outline", "ghost"] as const;

/** What the surface means. Orthogonal to {@link BADGE_VARIANTS}. */
export const BADGE_COLORS = ["default", "primary", "success", "warning", "danger", "info"] as const;

export const BADGE_SIZES = ["sm", "md", "lg"] as const;

export type BadgeVariant = (typeof BADGE_VARIANTS)[number];
export type BadgeColor = (typeof BADGE_COLORS)[number];
export type BadgeSize = (typeof BADGE_SIZES)[number];

/**
 * Theme token whose value gives an `Icon` composed into the badge its colour.
 *
 * The badge's counterpart to `BUTTON_FOREGROUND_TOKEN`, and it exists for the
 * same reason: a colour that has to reach an SVG paint prop cannot be a class.
 * Every entry names the token its own `label` slot resolves to, so a glyph and
 * the text beside it are always the same shade — a test asserts the pair.
 *
 * Nested rather than flattened to twenty-four keys so adding a colour is a
 * compile error in four places instead of a silent gap in one.
 */
export const BADGE_FOREGROUND_TOKEN: Record<BadgeVariant, Record<BadgeColor, string>> = {
	solid: {
		default: "secondary-foreground",
		primary: "primary-foreground",
		success: "success-foreground",
		warning: "warning-foreground",
		danger: "danger-foreground",
		info: "info-foreground",
	},
	soft: {
		default: "muted-foreground",
		primary: "tertiary-foreground",
		success: "success-soft-foreground",
		warning: "warning-soft-foreground",
		danger: "danger-soft-foreground",
		info: "info-soft-foreground",
	},
	outline: {
		default: "muted-foreground",
		primary: "foreground",
		success: "success-soft-foreground",
		warning: "warning-soft-foreground",
		danger: "danger-soft-foreground",
		info: "info-soft-foreground",
	},
	ghost: {
		default: "muted-foreground",
		primary: "foreground",
		success: "success-soft-foreground",
		warning: "warning-soft-foreground",
		danger: "danger-soft-foreground",
		info: "info-soft-foreground",
	},
};

/**
 * Styling for every part of a badge.
 *
 * Two axes rather than one. `variant` says how the surface is painted and
 * `color` says what it means, so a caller reaches `soft` + `warning` without the
 * library having to enumerate a `warning-soft` name for it — the combinatorial
 * growth `Button`'s single axis would pay here, where six semantic colours are
 * the point of the component rather than an afterthought. Neither axis carries a
 * surface on its own, so the twenty-four real pairings live in
 * `compoundVariants`.
 *
 * `self-start` is load-bearing. A badge is sized by its content, and inside a
 * gap column every child is stretch-aligned by default — without it, a one-word
 * badge spans the whole screen.
 *
 * `border border-transparent` sits in the base rather than on `outline` alone.
 * A border declared only where it is visible makes the badge two points wider
 * the moment a caller switches variant; reserving it in the box means `outline`
 * changes nothing but the colour.
 *
 * `overflow-hidden` is likewise not tidiness — a pressed badge fades to the
 * edge of its own capsule.
 *
 * A size is padding and never a height. `Text` respects OS font scaling, so a
 * fixed height clips the label at a large accessibility step instead of growing
 * with it, and unlike `h-button-*` a badge lines up against no chrome that would
 * force the number. The icon step indexes the shared `--spacing-icon-*` scale so
 * a glyph in a badge matches every other glyph in the library.
 *
 * The neutral end of the matrix reuses tokens the theme already has instead of
 * minting `--color-primary-soft`: this theme's `primary` is a near-black, whose
 * tint *is* the neutral fill, so a new token would duplicate `secondary` exactly.
 * `soft` takes `tertiary` for `primary` and `muted` for `default` — two fills the
 * theme already tunes per mode — which keeps all twenty-four cells distinct.
 *
 * The root holds no `text-*` utility: a React Native `View` does not cascade
 * colour to a `Text` descendant, so label colour lives on the `label` slot and
 * icon colour is resolved from {@link BADGE_FOREGROUND_TOKEN}.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const badgeVariants = tv({
	slots: {
		root: "flex-row items-center justify-center self-start overflow-hidden rounded-full border border-transparent",
		label: "text-center font-medium",
		startContent: "items-center justify-center",
		endContent: "items-center justify-center",
		closeButton: "items-center justify-center rounded-full",
		/** Edge length an `Icon` composed into the badge inherits. */
		icon: "",
	},
	variants: {
		// Neither axis paints a surface alone — see `compoundVariants`. What
		// each variant does carry is whether the box has a fill at all.
		variant: {
			solid: {},
			soft: {},
			outline: { root: "bg-transparent" },
			ghost: { root: "bg-transparent" },
		},
		color: {
			default: {},
			primary: {},
			success: {},
			warning: {},
			danger: {},
			info: {},
		},
		size: {
			sm: {
				root: "gap-1 px-2 py-0.5",
				label: "text-xs",
				closeButton: "-mr-0.5",
				icon: "size-icon-xs",
			},
			md: {
				root: "gap-1.5 px-2.5 py-1",
				label: "text-sm",
				closeButton: "-mr-1",
				icon: "size-icon-sm",
			},
			lg: {
				root: "gap-2 px-3 py-1.5",
				label: "text-base",
				closeButton: "-mr-1.5",
				icon: "size-icon-md",
			},
		},
		// The empty `false` branch is load-bearing typing, not a placeholder.
		// See the note in button.variants.ts.
		isDisabled: { true: { root: "opacity-50" }, false: {} },
	},
	compoundVariants: [
		{ variant: "solid", color: "default", class: { root: "bg-secondary", label: "text-secondary-foreground" } },
		{ variant: "solid", color: "primary", class: { root: "bg-primary", label: "text-primary-foreground" } },
		{ variant: "solid", color: "success", class: { root: "bg-success", label: "text-success-foreground" } },
		{ variant: "solid", color: "warning", class: { root: "bg-warning", label: "text-warning-foreground" } },
		{ variant: "solid", color: "danger", class: { root: "bg-danger", label: "text-danger-foreground" } },
		{ variant: "solid", color: "info", class: { root: "bg-info", label: "text-info-foreground" } },

		{ variant: "soft", color: "default", class: { root: "bg-muted", label: "text-muted-foreground" } },
		{ variant: "soft", color: "primary", class: { root: "bg-tertiary", label: "text-tertiary-foreground" } },
		{
			variant: "soft",
			color: "success",
			class: { root: "bg-success-soft", label: "text-success-soft-foreground" },
		},
		{
			variant: "soft",
			color: "warning",
			class: { root: "bg-warning-soft", label: "text-warning-soft-foreground" },
		},
		{ variant: "soft", color: "danger", class: { root: "bg-danger-soft", label: "text-danger-soft-foreground" } },
		{ variant: "soft", color: "info", class: { root: "bg-info-soft", label: "text-info-soft-foreground" } },

		{ variant: "outline", color: "default", class: { root: "border-border", label: "text-muted-foreground" } },
		{ variant: "outline", color: "primary", class: { root: "border-primary", label: "text-foreground" } },
		{
			variant: "outline",
			color: "success",
			class: { root: "border-success", label: "text-success-soft-foreground" },
		},
		{
			variant: "outline",
			color: "warning",
			class: { root: "border-warning", label: "text-warning-soft-foreground" },
		},
		{
			variant: "outline",
			color: "danger",
			class: { root: "border-danger", label: "text-danger-soft-foreground" },
		},
		{ variant: "outline", color: "info", class: { root: "border-info", label: "text-info-soft-foreground" } },

		{ variant: "ghost", color: "default", class: { label: "text-muted-foreground" } },
		{ variant: "ghost", color: "primary", class: { label: "text-foreground" } },
		{ variant: "ghost", color: "success", class: { label: "text-success-soft-foreground" } },
		{ variant: "ghost", color: "warning", class: { label: "text-warning-soft-foreground" } },
		{ variant: "ghost", color: "danger", class: { label: "text-danger-soft-foreground" } },
		{ variant: "ghost", color: "info", class: { label: "text-info-soft-foreground" } },
	],
	defaultVariants: {
		variant: "solid",
		color: "default",
		size: "md",
		isDisabled: false,
	},
});

/**
 * Whether the root should render as a `Pressable` rather than a plain `View`.
 *
 * A badge is content until a caller gives it something to do. Mounting a
 * `GestureDetector` regardless would put one under every tag in a list of fifty
 * and announce each of them to assistive technology as a button with no action.
 *
 * `onClose` is deliberately not read here: the dismiss control is its own
 * pressable, so a badge that can only be dismissed still has an inert root.
 *
 * Pure, so the matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveBadgeInteractive({
	onPress,
	onLongPress,
}: {
	onPress?: () => void;
	onLongPress?: () => void;
}): boolean {
	return onPress !== undefined || onLongPress !== undefined;
}

export type BadgeVariantProps = VariantProps<typeof badgeVariants>;

export { Badge, type BadgeProps } from "./badge";
export { type BadgeContextValue, BadgeProvider, useBadge, useBadgeContext } from "./badge.context";
export type { BadgeSlotProps } from "./badge.types";
export {
	BADGE_COLORS,
	BADGE_FOREGROUND_TOKEN,
	BADGE_SIZES,
	BADGE_VARIANTS,
	type BadgeColor,
	type BadgeSize,
	type BadgeVariant,
	type BadgeVariantProps,
	badgeVariants,
	resolveBadgeInteractive,
} from "./badge.variants";
export type { BadgeCloseButtonProps } from "./badge-close-button";
export type { BadgeLabelProps } from "./badge-label";
